INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1466, 'Lễ hội hoa đăng Cần Thơ 2018', 'le-hoi-hoa-dang-can-tho-2018', '<p>Lễ hội hoa đăng Cần Thơ là một ngày hội thường niên được tổ chức vào tháng 8 hàng năm. Năm nay lễ hội được tổ chức ở cầu tình yêu Cần Thơ với nhiều tiết mục đặc sắc. Ngoài một đêm hoa đăng với những sắc màu lung linh về đêm, lễ hội lần này còn được tổ chức với nhiều sự kiện bên lề khác. Bạn sẽ được tham quan những gian hàng đặc sắc về văn hóa như thư pháp, những gian hàng trưng bày trái cây,&#8230;</p>
<p>Lễ hội là một dịp quảng bá du lịch cho bến Ninh Kiều. Nơi được xem là điểm du lịch, vui chơi giải trí tuyệt vời của Cần Thơ. Bến Ninh Kiều thơ mộng trong những bài thơ:</p>
<p><em>&#8220;Cần Thơ có bến Ninh Kiều.</em><br />
<em>Có người con gái mỗi chiều đợi trông.&#8221;</em></p>
<p><iframe src="https://www.youtube.com/embed/cIc7qAsu6I0" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<h2>Nhiều Sự Kiện Thú Vị Diễn Ra Ngay Tại Bến Ninh Kiều</h2>
<p>Nhiều sự kiện bên lề được tổ chức khác nhau được tổ chức như:&nbsp;Giải Đua thuyền truyền thống thành phố Cần Thơ, hình ảnh, thư pháp và ký họa chân dung; hội diễn “Flashmob &#8211; kết nối tuổi trẻ; các hoạt động hoạt náo dân gian và âm nhạc đường phố…</p>
<p><figure id="attachment_1467" aria-describedby="caption-attachment-1467" style="width: 5472px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1467" src="https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ2.jpg" alt="Một du khách chờ đón lễ hội khai mạc" width="5472" height="3072" srcset="https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ2.jpg 5472w, https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ2-768x431.jpg 768w" sizes="(max-width: 5472px) 100vw, 5472px" /><figcaption id="caption-attachment-1467" class="wp-caption-text">Một du khách chờ đón lễ hội khai mạc</figcaption></figure></p>
<h2>Lung Linh Ngày Lễ Hội Hoa Đăng</h2>
<p>Đến Ngày hội ở bến Ninh Kiều, du khách sẽ được chiêm ngưỡng mô hình cặp rồng cao 4 mét, dài 12 mét, rộng 4 mét có ý nghĩa minh họa cho tên gọi Rạch Khai Luông nghĩa là mở hướng rồng bay; 60 hoa đăng lớn &#8211; minh họa cho ý nghĩa 60 năm ngày hình thành Bến Ninh Kiều. Bạn sẽ được thưởng thức những tiết mục văn nghệ tuyệt vời trong đêm lễ hội.</p>
<p><figure id="attachment_1469" aria-describedby="caption-attachment-1469" style="width: 5472px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1469" src="https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ4.jpg" alt="Văn nghệ hội hoa đăng" width="5472" height="3072" srcset="https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ4.jpg 5472w, https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ4-768x431.jpg 768w" sizes="(max-width: 5472px) 100vw, 5472px" /><figcaption id="caption-attachment-1469" class="wp-caption-text">Văn nghệ hội hoa đăng</figcaption></figure></p>
<p>Hay bạn sẽ bắt gặp những chiếc lồng đèn rực rỡ sáng lung linh trong đêm ở bến Ninh Kiều.</p>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1468" src="https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ3.jpg" alt="" width="5472" height="3072" srcset="https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ3.jpg 5472w, https://media.huynhhieutravel.com/Hội-hoa-đăng-Cần-Thơ3-768x431.jpg 768w" sizes="(max-width: 5472px) 100vw, 5472px" /></p>
<p>Nhiều gian hàng trang trí đặc sắc với những trái cây đặc trưng của miền Tây. Bạn cũng có thể chụp hình cùng những tiểu cảnh được trang trí đậm nét chủ đề hoa đăng.</p>
<p><figure id="attachment_1462" aria-describedby="caption-attachment-1462" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1462" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ14.jpg" alt="Lễ hội hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ14.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ14-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1462" class="wp-caption-text">Lễ hội hoa đăng cần thơ</figcaption></figure></p>
<p>Hay bắt gặp những gian hàng được trang trí những cảnh sắc đặc trưng của Cần Thơ như chợ Cần Thơ.</p>
<p><figure id="attachment_1452" aria-describedby="caption-attachment-1452" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1452" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ3.jpg" alt="Tiểu cảnh ở lễ hội hoa đăng" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ3.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ3-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1452" class="wp-caption-text">Tiểu cảnh chợ Cần Thơ</figcaption></figure></p>
', 'Lễ hội hoa đăng Cần Thơ là một ngày hội thường niên được tổ chức vào tháng 8 hàng năm. Năm nay lễ hội được tổ chức ở cầu tình yêu Cần Thơ với nhiều tiết mục đặc sắc. Ngoài một đêm hoa đăng với những sắc màu lung linh về đêm, lễ hội lần [&hellip;]', 1467, 'post', '2018-08-12 15:58:55', '2023-04-23 12:47:37');

