INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1449, 'Lễ hội hoa đăng Cần Thơ có những gì?', 'le-hoi-hoa-dang-can-tho-co-nhung-gi', '<p>Lễ khai mạc lễ hội hoa đăng Cần Thơ đã được bắt đầu vào 19h00 ngày 10 tháng 8 năm 2018. Cùng Huynh Hieu Travel tìm hiểu bên trong có gì nhé! Tôi đã có mặt tại trung tâm và chuẩn bị những hình ảnh mới nhất cho các bạn.</p>
<h2>Lễ hội hoa đăng Cần Thơ có những gì?</h2>
<p>Cổng chào của Lễ hội làm khá đơn sơ và đặt ngay tại bến Ninh Kiều.</p>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1450" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ.jpg" alt="" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /></p>
<p>Bên trong là nhiều gian hàng khác nhau. Những gian hàng được trang trí những tiểu cảnh tiêu biểu cho Cần Thơ.</p>
<p><figure id="attachment_1452" aria-describedby="caption-attachment-1452" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1452" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ3.jpg" alt="Tiểu cảnh ở lễ hội hoa đăng" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ3.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ3-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1452" class="wp-caption-text">Triển lãm sách ở Cần Thơ</figcaption></figure></p>
<p>Một gian hàng lung linh để bạn tỏa sáng khi tự sướng!</p>
<p><figure id="attachment_1462" aria-describedby="caption-attachment-1462" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1462" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ14.jpg" alt="Lễ hội hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ14.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ14-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1462" class="wp-caption-text">Lễ hội hoa đăng cần thơ</figcaption></figure></p>
<p>Và nhiều gian hàng khác nhau để bạn tham quan và mua sắm.</p>
<p><figure id="attachment_1454" aria-describedby="caption-attachment-1454" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1454" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ5.jpg" alt="Gian hàng hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ5.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ5-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1454" class="wp-caption-text">Gian hàng hoa đăng cần thơ</figcaption></figure></p>
<p><figure id="attachment_1455" aria-describedby="caption-attachment-1455" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1455" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ6.jpg" alt="Gian hàng hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ6.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ6-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1455" class="wp-caption-text">Gian hàng hoa đăng cần thơ</figcaption></figure></p>
<p><figure id="attachment_1456" aria-describedby="caption-attachment-1456" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1456" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ7.jpg" alt="Gian hàng hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ7.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ7-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1456" class="wp-caption-text">Gian hàng hoa đăng cần thơ</figcaption></figure></p>
<p><figure id="attachment_1457" aria-describedby="caption-attachment-1457" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1457" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ8.jpg" alt="Gian hàng hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ8.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ8-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1457" class="wp-caption-text">Gian hàng hoa đăng cần thơ</figcaption></figure></p>
<p><figure id="attachment_1458" aria-describedby="caption-attachment-1458" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1458" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ9.jpg" alt="Gian hàng hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ9.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ9-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1458" class="wp-caption-text">Gian hàng hoa đăng cần thơ</figcaption></figure></p>
<p><figure id="attachment_1459" aria-describedby="caption-attachment-1459" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1459" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ10.jpg" alt="Gian hàng hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ10.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ10-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1459" class="wp-caption-text">Gian hàng hoa đăng cần thơ</figcaption></figure></p>
<p><figure id="attachment_1461" aria-describedby="caption-attachment-1461" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1461" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ13.jpg" alt="Gian hàng hoa đăng cần thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ13.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ13-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1461" class="wp-caption-text">Gian hàng hoa đăng cần thơ</figcaption></figure></p>
<p><figure id="attachment_1460" aria-describedby="caption-attachment-1460" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1460" src="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ12.jpg" alt="Cầu tình yêu Cần Thơ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ12.jpg 960w, https://media.huynhhieutravel.com/Lễ-hội-hoa-đăng-cần-thơ12-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1460" class="wp-caption-text">Cầu tình yêu Cần Thơ</figcaption></figure></p>
