INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1433, 'Hơn 1000 bạn trẻ tham dự Hội trại Tuổi trẻ Phật Giáo ở Phan Thiết', '1000-ban-tre-du-hoi-trai-tuoi-tre-phat-giao', '<p>Ngày 20 tháng 7 năm 2018, Ban hướng dẫn phật tử tỉnh Bình Thuận phối hợp cùng ban hướng dẫn phật tử Trung ương chính thức khai mạc ngày Hội trại Tuổi trẻ Phật giáo ở Phan Thiết năm 2018 lần thứ 13 với chủ đề &#8220;Tuổi Thanh Xuân&#8221;. Hội trại được tổ chức trong 3 ngày 2 đêm từ ngày 20 đến ngày 23 tháng 7 năm 2018. Ngày hội diễn ra thành công rực rỡ với hơn 1000 bạn thanh thiếu niên tham dự.</p>
<p><figure id="attachment_1241" aria-describedby="caption-attachment-1241" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1241" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo34.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo34.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo34-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1241" class="wp-caption-text">Hơn 1000 trại sinh ở Hội trại tuổi trẻ phật giáo</figcaption></figure></p>
<p>Hội trại Tuổi trẻ Phật giáo với sự tham gia của hơn 1000 bạn từ độ tuổi 14 đến 32 tuổi ở đủ mọi miền tổ quốc và cả những trại sinh quốc tế đến từ Singapore, Thái Lan, Hàn Quốc,&#8230; Đây là những thanh thiếu niên nhiệt tình và đầy hoài bão với tuổi trẻ thanh xuân cống hiến cho tổ quốc và làm những điều đẹp đẽ cho cuộc sống.</p>
<p><iframe src="https://www.youtube.com/embed/MxqOo2ui1eg" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<p>ĐĐ.Thích An Đạt, Phó ban kiêm Chánh Thư ký Ban Tổ chức Hội trại chia sẽ: “Hội trại lần này với mong muốn tuổi trẻ phải trọn vẹn trong từng hơi thở tuổi thanh xuân, tràn đầy yêu thương an vui. Đồng thời tạo một môi trường tham quan và vui chơi trong mùa hè, giúp các bạn giải tỏa stress sau những ngày học tập và làm việc căng thẳng. Bạn sẽ có những phút giây tuyệt vời bên ánh lửa trại đêm khuya với bạn bè bốn phương, sáng sớm ngồi tĩnh lặng nghe sóng vỗ và ngắm mặt trời lên, bước những bước thảnh thơi mà trước mặt là biển cả bao la”.</p>
<p>Chi tiết Thông tin Hội Trại:</p>
<blockquote class="wp-embedded-content" data-secret="nKBOFpLLE9"><p><a href="https://huynhhieutravel.com/hoi-trai-tuoi-tre-phat-giao/">Hội Trại Tuổi Trẻ Phật Giáo 2018 | Tuổi Thanh Xuân</a></p></blockquote>
<p><iframe class="wp-embedded-content" sandbox="allow-scripts" security="restricted" style="position: absolute; clip: rect(1px, 1px, 1px, 1px);" title="&#8220;Hội Trại Tuổi Trẻ Phật Giáo 2018 | Tuổi Thanh Xuân&#8221; &#8212; Huỳnh Hiếu Travel" src="https://huynhhieutravel.com/hoi-trai-tuoi-tre-phat-giao/embed/#?secret=CyzSgexJRM#?secret=nKBOFpLLE9" data-secret="nKBOFpLLE9" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<h2>Hướng đến chân, thiện, mỹ trong giáo lý Phật pháp</h2>
<p>Hội trại với nhiều hoạt động nổi bật hướng giới trẻ đến chân, thiện, mỹ. Hội trại tổ chức với nhiều hoạt động ý nghĩa về Phật pháp khác nhau như: Đốt hoa đăng cầu nguyện, buổi thuyết giảng và tụng kinh cầu nguyện, thiền định, thi phật pháp,&#8230;</p>
<p><figure id="attachment_1425" aria-describedby="caption-attachment-1425" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1425" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1425" class="wp-caption-text">Một trại sinh đặt câu hỏi về Phật pháp trong Hội Trại</figcaption></figure></p>
<p>Đặc biệt Hội trại Tuổi trẻ Phật giáo còn đưa ra nhiều hoạt động sinh hoạt tích cực cho giới trẻ. Những trò chơi lớn, nhỏ, tham quan hội trại và sinh hoạt thú vị cùng nhau. Những bạn trẻ sẽ có thời gian lắng động và sôi nổi với tuổi thanh xuân của mình.</p>
<p><figure id="attachment_1263" aria-describedby="caption-attachment-1263" style="width: 987px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1263 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo56.jpg" alt="Hội trại tuổi trẻ phật giáo ở Phan Thiết" width="987" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo56.jpg 987w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo56-768x477.jpg 768w" sizes="(max-width: 987px) 100vw, 987px" /><figcaption id="caption-attachment-1263" class="wp-caption-text">Không khí vui tươi ở Hội trại tuổi trẻ phật giáo</figcaption></figure></p>
<p>Những hoạt động vui tươi diễn ra vô cùng náo nhiệt nhưng cũng vô cùng kỷ luật. Các bạn trẻ học tập đức tính tốt từ giáo lý nhà Phật, vừa hòa mình cùng thiên nhiên, vừa sôi nổi cùng tuổi thanh xuân rực rỡ của mình.</p>
<p><figure id="attachment_1395" aria-describedby="caption-attachment-1395" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1395 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo188.jpg" alt="Tình nguyện viên vui vẻ nhảy cùng nhau" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo188.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo188-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1395" class="wp-caption-text">Tình nguyện viên vui vẻ nhảy cùng nhau</figcaption></figure></p>
<p>Tại lễ khai mạc, ban tổ chức đã gửi tặng những quà tặng kỷ niệm đến những tình nguyện viên đã đóng góp công sức của mình cho một kỳ Hội trại thành công.</p>
<p><figure id="attachment_1343" aria-describedby="caption-attachment-1343" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1343 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo136.jpg" alt="Ban quản trại của hội trại tuổi trẻ phật giáo lần thứ 13" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo136.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo136-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1343" class="wp-caption-text">Ban quản trại của hội trại tuổi trẻ phật giáo lần thứ 13</figcaption></figure></p>
<h2>Một kỳ Hội trại tuổi trẻ Phật giáo ở Phan Thiết thành công</h2>
<p>Trước đó một ngày hơn 1000 trại sinh đã hòa mình và lắng đọng với chương trình Đêm Yêu Thương với chủ đề Tuổi Thanh Xuân. Các bạn trẻ đã trải nghiệm, chia sẽ những dòng lưu ký về tuổi thanh xuân của mình. Tuổi thanh xuân với những chuyện gia đình, những lo ưu về tương lai hay những trải nghiệm về một tuổi thơ tuyệt vời.</p>
<p><figure id="attachment_1420" aria-describedby="caption-attachment-1420" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1420 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-213.jpg" alt="Trại sinh viết thư gửi yêu thương với chủ đề tuổi thanh xuân" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-213.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-213-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1420" class="wp-caption-text">Trại sinh viết thư gửi yêu thương với chủ đề tuổi thanh xuân</figcaption></figure></p>
<p>Hội trại sẽ được tiếp tục diễn ra vào năm sau vào thời gian tháng 7, hãy cùng đón chờ kỳ hội trại 14 vào năm 2019 bạn nhé!</p>
<p><iframe src="https://www.youtube.com/embed/6c1puPinnP4" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
', 'Ngày 20 tháng 7 năm 2018, Ban hướng dẫn phật tử tỉnh Bình Thuận phối hợp cùng ban hướng dẫn phật tử Trung ương chính thức khai mạc ngày Hội trại Tuổi trẻ Phật giáo ở Phan Thiết năm 2018 lần thứ 13 với chủ đề &#8220;Tuổi Thanh Xuân&#8221;. Hội trại được tổ chức trong [&hellip;]', 1347, 'post', '2018-08-02 09:51:07', '2023-04-23 12:25:52');

